<?php
declare(strict_types=1);
require_once __DIR__ . '/bootstrap.php';
$admin = requireAdmin();
$db = adminDb();
require_once __DIR__ . '/db-install.php';

function h(mixed $v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function countq(PDO $db,string $sql,array $p=[]):int{try{$q=$db->prepare($sql);$q->execute($p);return(int)$q->fetchColumn();}catch(Throwable){return 0;}}
function rowsq(PDO $db,string $sql,array $p=[]):array{try{$q=$db->prepare($sql);$q->execute($p);return$q->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable){return[];}}
$tab=(string)($_GET['tab']??'dashboard'); if(!in_array($tab,['dashboard','analytics','ads','settings','users'],true))$tab='dashboard';
if($_SERVER['REQUEST_METHOD']==='POST'){verifyAdminCsrf();$a=(string)($_POST['action']??'');try{
if($a==='ad_save'){$id=(int)($_POST['id']??0);$key=trim((string)$_POST['ad_key']);$code=(string)$_POST['ad_code'];$enabled=!empty($_POST['enabled'])?1:0;if($id){$q=$db->prepare('UPDATE ads_settings SET ad_key=?,enabled=?,ad_code=? WHERE id=?');$q->execute([$key,$enabled,$code,$id]);}else{$q=$db->prepare('INSERT INTO ads_settings(ad_key,enabled,ad_code) VALUES(?,?,?)');$q->execute([$key,$enabled,$code]);}adminAudit('save_ad','ads_settings',(string)$id,$key);header('Location:?tab=ads');exit;}
if($a==='ad_delete'){$id=(int)$_POST['id'];$q=$db->prepare('DELETE FROM ads_settings WHERE id=?');$q->execute([$id]);adminAudit('delete_ad','ads_settings',(string)$id);header('Location:?tab=ads');exit;}
if($a==='setting_save'){$id=(int)($_POST['id']??0);$key=trim((string)$_POST['setting_key']);$value=(string)$_POST['setting_value'];$type=(string)$_POST['setting_type'];$desc=trim((string)$_POST['description']);$enabled=!empty($_POST['enabled'])?1:0;if($id){$q=$db->prepare('UPDATE smarttoolz_settings SET setting_key=?,setting_value=?,setting_type=?,description=?,enabled=? WHERE id=?');$q->execute([$key,$value,$type,$desc,$enabled,$id]);}else{$q=$db->prepare('INSERT INTO smarttoolz_settings(setting_key,setting_value,setting_type,description,enabled) VALUES(?,?,?,?,?)');$q->execute([$key,$value,$type,$desc,$enabled]);}adminAudit('save_setting','smarttoolz_settings',(string)$id,$key);header('Location:?tab=settings');exit;}
if($a==='setting_delete'){$id=(int)$_POST['id'];$q=$db->prepare('DELETE FROM smarttoolz_settings WHERE id=?');$q->execute([$id]);adminAudit('delete_setting','smarttoolz_settings',(string)$id);header('Location:?tab=settings');exit;}
if($a==='user_role'){$id=(int)$_POST['id'];$role=(string)$_POST['role'];if(!in_array($role,['user','admin','superadmin'],true))$role='user';$q=$db->prepare('SELECT email FROM creator_users WHERE id=?');$q->execute([$id]);$email=(string)$q->fetchColumn();if(strtolower($email)===strtolower(SMARTTOOLZ_ADMIN_EMAIL))$role='admin';$q=$db->prepare('UPDATE creator_users SET role=? WHERE id=?');$q->execute([$role,$id]);adminAudit('user_role','creator_users',(string)$id,$email.' => '.$role);header('Location:?tab=users');exit;}
if($a==='user_credits'){$id=(int)$_POST['id'];$c=max(0,(int)$_POST['credits']);$d=max(0,(int)$_POST['daily_credits']);$q=$db->prepare('UPDATE creator_users SET credits=?,daily_credits=? WHERE id=?');$q->execute([$c,$d,$id]);adminAudit('user_credits','creator_users',(string)$id,'credits='.$c.',daily='.$d);header('Location:?tab=users');exit;}
}catch(Throwable $e){$_SESSION['admin_flash']=$e->getMessage();header('Location:?tab='.rawurlencode($tab));exit;}}
$flash=$_SESSION['admin_flash']??'';unset($_SESSION['admin_flash']);$csrf=adminCsrf();
$live=countq($db,"SELECT COUNT(*) FROM analytics_live WHERE last_seen>=DATE_SUB(NOW(),INTERVAL 5 MINUTE)");
$views=countq($db,"SELECT COUNT(*) FROM analytics_pageviews WHERE viewed_at>=CURDATE()");
$vis=countq($db,"SELECT COUNT(DISTINCT visitor_id) FROM analytics_pageviews WHERE viewed_at>=CURDATE()");
$downloads=countq($db,"SELECT COUNT(*) FROM download_tracking WHERE created_at>=CURDATE()");
$totalViews=countq($db,'SELECT COUNT(*) FROM analytics_pageviews');$totalDownloads=countq($db,'SELECT COUNT(*) FROM download_tracking');
$users=rowsq($db,'SELECT id,name,email,role,credits,daily_credits,plan,created_at FROM creator_users ORDER BY id DESC LIMIT 300');
$ads=rowsq($db,'SELECT * FROM ads_settings ORDER BY id DESC');$settings=rowsq($db,'SELECT * FROM smarttoolz_settings ORDER BY setting_key ASC');
$pages=rowsq($db,"SELECT page_path,COUNT(*) c FROM analytics_pageviews WHERE viewed_at>=DATE_SUB(NOW(),INTERVAL 30 DAY) GROUP BY page_path ORDER BY c DESC LIMIT 12");
$tools=rowsq($db,"SELECT tool_slug,COUNT(*) c FROM tool_usage GROUP BY tool_slug ORDER BY c DESC LIMIT 12");
$countries=rowsq($db,"SELECT COALESCE(NULLIF(country,''),'Unknown') label,COUNT(*) c FROM analytics_pageviews WHERE viewed_at>=DATE_SUB(NOW(),INTERVAL 30 DAY) GROUP BY country ORDER BY c DESC LIMIT 12");
$devices=rowsq($db,"SELECT COALESCE(NULLIF(device,''),'Other') label,COUNT(*) c FROM analytics_pageviews WHERE viewed_at>=DATE_SUB(NOW(),INTERVAL 30 DAY) GROUP BY device ORDER BY c DESC LIMIT 8");
$browsers=rowsq($db,"SELECT COALESCE(NULLIF(browser,''),'Other') label,COUNT(*) c FROM analytics_pageviews WHERE viewed_at>=DATE_SUB(NOW(),INTERVAL 30 DAY) GROUP BY browser ORDER BY c DESC LIMIT 8");
$liveRows=rowsq($db,"SELECT visitor_id,page_path,country,city,device,browser,last_seen FROM analytics_live WHERE last_seen>=DATE_SUB(NOW(),INTERVAL 5 MINUTE) ORDER BY last_seen DESC LIMIT 50");
$editAd=null;$editSetting=null;if(isset($_GET['edit'])&&$tab==='ads'){$r=rowsq($db,'SELECT * FROM ads_settings WHERE id=?',[(int)$_GET['edit']]);$editAd=$r[0]??null;}if(isset($_GET['edit'])&&$tab==='settings'){$r=rowsq($db,'SELECT * FROM smarttoolz_settings WHERE id=?',[(int)$_GET['edit']]);$editSetting=$r[0]??null;}
?>
