<div class="section split-card"><section class="admin-card panel"><div class="section-head"><div><h2>Live Visitors</h2><p>Updates every second</p></div><span class="tag tag-green">LIVE</span></div><div class="live-list" data-live-box><?php foreach($liveRows as $r):?><div class="live-item"><span class="live-dot"></span><div class="live-main"><div class="live-title"><?=h($r['page_path'])?></div><div class="live-sub"><?=h(implode(' · ',array_filter([$r['country']??'Unknown',$r['city']??'',$r['device']??'',$r['browser']??''])))?></div></div><span class="live-time">now</span></div><?php endforeach;if(!$liveRows):?><div class="empty">No active visitors.</div><?php endif;?></div></section><section class="admin-card panel"><div class="section-head"><div><h2>Quick Actions</h2><p>Jump straight to management</p></div></div><div class="toolbar"><a class="btn btn-primary" href="?tab=analytics">Open Analytics</a><a class="btn" href="/smart-toolz/admin/db-browser.php">DB Explorer</a><a class="btn" href="?tab=ads">Ads</a><a class="btn" href="?tab=users">Users</a><a class="btn" href="?tab=settings">Settings</a></div><div class="section"><div class="notice">Database + analytics are admin-only. The DB Explorer is read-only to reduce accidental destructive changes.</div></div></section></div>
