</h2><p>30-day split</p></div></div><?php $mx=max(1,(int)($devices[0]['c']??1));?><div class="bar-list"><?php foreach($devices as $r):?><div class="bar-row"><div class="bar-name"><?=h($r['label'])?></div><div class="bar-track"><div class="bar-fill" style="width:<?=min(100,(int)round($r['c']/$mx*100))?>%"></div></div><div class="bar-count"><?=number_format((int)$r['c'])?></div></div><?php endforeach;?></div></section><section class="admin-card panel"><div class="section-head"><div><h2>Browsers</h2><p>30-day split</p></div></div><?php $mx=max(1,(int)($browsers[0]['c']??1));?><div class="bar-list"><?php foreach($browsers as $r):?><div class="bar-row"><div class="bar-name"><?=h($r['label'])?></div><div class="bar-track"><div class="bar-fill" style="width:<?=min(100,(int)round($r['c']/$mx*100))?>%"></div></div><div class="bar-count"><?=number_format((int)$r['c'])?></div></div><?php endforeach;?></div></section></div><div class="section admin-card panel"><div class="section-head"><div><h2>Realtime Table</h2><p>Current active sessions</p></div></div><div class="table-wrap"><table><thead><tr><th>Visitor</th><th>Page</th><th>Country / City</th><th>Device</th><th>Browser</th><th>Last Seen</th></tr></thead><tbody><?php foreach($liveRows as $r):?><tr><td><?=h(substr((string)$r['visitor_id'],0,12))?>…</td><td><?=h($r['page_path'])?></td><td><?=h(trim(($r['country']??'Unknown').' '.($r['city']??'')))?></td><td><?=h($r['device'])?></td><td><?=h($r['browser'])?></td><td><?=h($r['last_seen'])?></td></tr><?php endforeach;if(!$liveRows):?><tr><td colspan="6" class="empty">No active visitors.</td></tr><?php endif;?></tbody></table></div></div>
